@keyframes antigravityFloat {
  0% { transform: translateY(0px); }
  40% { transform: translateY(-15px); }
  60% { transform: translateY(-15px); }
  100% { transform: translateY(0px); }
}
.floating-icon {
  opacity: 0;
  animation: fadeIn 0.4s ease-in forwards, antigravityFloat 4s ease-in-out infinite;
  animation-delay: 0.4s, 0.4s;
}
.floating-icon-static {
  opacity: 1;
  transform: translateY(-15px);
}
@keyframes ripple {
  0% {
    transform: scale(0.6);
    opacity: 0;
  }
  10% {
    opacity: 0.3;
  }
  100% {
    transform: scale(2.5);
    opacity: 0;
  }
}
.ripple-container {
  position: relative;
  display: inline-block;
}
.ripple {
  position: absolute;
  bottom: -10px;
  left: 50%;
  margin-left: -40px;
  width: 80px;
  height: 16px;
  border: 2px solid rgba(99, 102, 241, 0.5);
  border-radius: 50%;
  opacity: 0;
  animation: ripple 4s ease-out infinite;
  animation-fill-mode: backwards;
  transform-origin: center center;
}
.ripple:nth-of-type(1) {
  animation-delay: 0.8s;
}
.ripple:nth-of-type(2) {
  animation-delay: 2.1s;
}
.ripple:nth-of-type(3) {
  animation-delay: 3.4s;
}

@keyframes dot-bounce {
  0%, 100% {
    transform: translateY(0);
  }
  15% {
    transform: translateY(-2px); /* Subtle bounce for 3px dots */
  }
  30% {
    transform: translateY(0);
  }
}
.animate-dot-bounce {
  animation: dot-bounce 1.6s ease-in-out infinite;
}

