.theme-standalone .message-prompt-card-tool { border-color: rgba(13, 148, 136, 0.35); }
.theme-standalone .message-prompt-card-system { border-color: rgba(168, 85, 247, 0.35); }
.theme-standalone .message-prompt-card-unknown { border-color: rgba(63, 63, 70, 0.3); }

.context-cell-selected {
  box-shadow: 0 0 0 2px #eab308 !important;
}
.context-cell-hovered,
.context-cell-unused:hover {
  box-shadow: 0 0 0 1px rgba(234, 179, 8, 0.8) !important;
}
.context-tooltip {
  border-color: rgba(234, 179, 8, 0.8) !important;
}
.timeline-tooltip {
  --rt-color-border: rgba(234, 179, 8, 0.8) !important;
  border-color: rgba(234, 179, 8, 0.8) !important;
}

.step-grid-row {
  display: grid;
  grid-template-columns: 50px 50px 55px 140px 1fr 70px 80px 80px;
  align-items: center;
  border-top: 1px solid var(--border-color, #303030);
  box-sizing: border-box;
  position: relative;
  height: 32px;
  margin-bottom: -1px;
  scroll-margin-top: 32px;
}
.step-grid-row.sticky {
  position: sticky !important;
}

/* Row Status Backgrounds */
.row-excluded {
  background-color: color-mix(in srgb, var(--color-red-500) 12%, var(--background)) !important;
  border-top-color: color-mix(in srgb, var(--color-red-500) 25%, var(--border)) !important;
}
.row-active {
  background-color: var(--background) !important;
  border-top-color: var(--border) !important;
}
.row-ignored {
  background-color: var(--muted) !important;
  border-top-color: var(--border) !important;
  opacity: 0.75;
}

.dark .row-excluded {
  background-color: #2c1d1d !important;
  border-top-color: #3d2525 !important;
  opacity: 1;
}
.dark .row-active {
  background-color: #1e1e1e !important;
  border-top-color: #2d2d2d !important;
}
.dark .row-ignored {
  background-color: #141414 !important;
  border-top-color: #1f1f1f !important;
  opacity: 1;
}

/* Pseudo-elements for Group Highlighting (Yellow/Amber Theme) - Thicker 3px */
.group-selected-top::after,
.group-selected-bottom::after,
.group-selected-middle::after,
.group-selected-single::after,
.group-hover-top::after,
.group-hover-bottom::after,
.group-hover-middle::after,
.group-hover-single::after {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  pointer-events: none;
  box-sizing: border-box;
}

.group-selected-top::after {
  border-top: 3px solid #eab308;
  border-left: 3px solid #eab308;
  border-right: 3px solid #eab308;
  z-index: 10;
}
.group-selected-bottom::after {
  border-bottom: 3px solid #eab308;
  border-left: 3px solid #eab308;
  border-right: 3px solid #eab308;
  z-index: 10;
}
.group-selected-middle::after {
  border-left: 3px solid #eab308;
  border-right: 3px solid #eab308;
  z-index: 10;
}
.group-selected-single::after {
  border: 3px solid #eab308;
  z-index: 10;
}

/* Nested Selected Step Outline - Thinner/Subtler 1px with 35% opacity */
.selected-step-outline::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  border: 1px solid rgba(234, 179, 8, 0.35);
  pointer-events: none;
  z-index: 20;
}

/* Bolder Hover Preview for Groups (60% opacity yellow) - Thicker 3px */
.group-hover-top::after {
  border-top: 3px solid rgba(234, 179, 8, 0.6);
  border-left: 3px solid rgba(234, 179, 8, 0.6);
  border-right: 3px solid rgba(234, 179, 8, 0.6);
  z-index: 5;
}
.group-hover-bottom::after {
  border-bottom: 3px solid rgba(234, 179, 8, 0.6);
  border-left: 3px solid rgba(234, 179, 8, 0.6);
  border-right: 3px solid rgba(234, 179, 8, 0.6);
  z-index: 5;
}
.group-hover-middle::after {
  border-left: 3px solid rgba(234, 179, 8, 0.6);
  border-right: 3px solid rgba(234, 179, 8, 0.6);
  z-index: 5;
}
.group-hover-single::after {
  border: 3px solid rgba(234, 179, 8, 0.6);
  z-index: 5;
}

/* Segment Hover Highlight (from Context Bar) */
.segment-hover-row-highlight {
  background-color: rgba(234, 179, 8, 0.12) !important;
  box-shadow: inset 0 0 0 1px #eab308 !important;
  z-index: 20;
}

/* Subtle yellow background tints for grouped items */
.group-bg-selected::after {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  background-color: rgba(234, 179, 8, 0.03);
  pointer-events: none;
  z-index: 1;
}
.group-bg-hover::after {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  background-color: rgba(234, 179, 8, 0.02) !important; /* Stronger tint */
  pointer-events: none;
  z-index: 1;
}

/* Dynamic Step Hovers (blend with semantic row backgrounds) */
.step-hover-prominent {
  background-color: rgba(255, 255, 255, 0.08) !important; /* Noticeable highlight for Step mode */
}
.step-hover-subtle {
  background-color: rgba(255, 255, 255, 0.025) !important; /* Very soft highlight for group modes */
}
